// Generated by build.py. Caches the whole site on install so it works offline;
// a new build changes VERSION, which installs a fresh cache and drops the old one.
const VERSION = "terrafolio-bfeae8319537";
const FILES = [
  "./",
  "app.js",
  "chapter-01.html",
  "chapter-02.html",
  "chapter-03.html",
  "chapter-04.html",
  "chapter-05-06-07.html",
  "chapter-08.html",
  "chapter-09.html",
  "chapter-10.html",
  "chapter-11.html",
  "chapter-12.html",
  "chapter-13.html",
  "chapter-14.html",
  "chapter-15.html",
  "chapter-16.html",
  "chapter-17.html",
  "chapter-18.html",
  "chapter-19.html",
  "data.json",
  "icons/apple-touch-icon.png",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "index.html",
  "library.html",
  "manifest.webmanifest",
  "notes.html",
  "progress.html",
  "style.css"
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(VERSION).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    caches.match(event.request, { ignoreSearch: true }).then((hit) =>
      hit || fetch(event.request).catch(() =>
        event.request.mode === "navigate" ? caches.match("./") : Response.error()
      )
    )
  );
});
